static class Book { String title, author; int pages; }
public class Main {
    public static void main(String[] args) {}
}

exercises.solution:
public class Main {
    static class Book { String title="", author=""; int pages; public String toString() {
            String sep = author.isEmpty() ? "  " : " " + author + " ";
            return "{" + title + sep + pages + "}";
        } }

    public static void main(String[] args) {
        Book b = new Book(); b.title = "Go Programming";
        System.out.println(b);
    }
}

